"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["36283"],{76278(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.escopo_obrigatorio","status":422,"titulo":"Escopo do fato \xe9 obrigat\xf3rio"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.escopo_obrigatorio","requisitos":["UNI-REQ-0143","UNI-REQ-0146","UNI-REQ-0159"],"oQueAconteceu":["O escopo diz quem responde ao fato: o pr\xf3prio candidato, uma \xfanica vez, ou cada membro de um grupo repet\xedvel, como a composi\xe7\xe3o familiar (UNI-REQ-0146). O cadastro de um fato declarado (`POST /api/configuracao/admin/fatos-candidato`) ou derivado por regra (`POST /api/configuracao/admin/fatos-candidato/derivados`) chegou com o `escopo` vazio, s\xf3 com espa\xe7os ou com um valor que n\xe3o \xe9 do vocabul\xe1rio, ou a altera\xe7\xe3o da defini\xe7\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`) de um fato declarado ou derivado chegou sem ele. Para o escopo, as duas situa\xe7\xf5es recebem este mesmo c\xf3digo de erro.","A recusa vem na lista `errors` da resposta, com `field` igual a `escopo`. Nada \xe9 gravado. O campo ausente do corpo do cadastro \xe9 recusado antes, como erro de requisi\xe7\xe3o (400). No fato de sistema, que s\xf3 aceita mudar o nome, a descri\xe7\xe3o, a forma de exibi\xe7\xe3o e a prote\xe7\xe3o de dados, um escopo fora do vocabul\xe1rio tamb\xe9m recebe esta recusa, antes da recusa de [defini\xe7\xe3o do fato de sistema travada](/erros/uniplus.configuracao.fato_candidato.definicao_do_fato_de_sistema_travada). O resumo de grupo n\xe3o informa o escopo: quem o envia recebe [a recusa de eixo que o tipo do fato n\xe3o permite alterar](/erros/uniplus.configuracao.fato_candidato.eixo_nao_editavel_no_tipo_do_fato)."],"comoResolver":["Informe o escopo, escrito exatamente assim, em mai\xfasculas:","- `CANDIDATO`: o pr\xf3prio candidato responde, uma \xfanica vez;\\n- `MEMBRO_GRUPO`: cada membro de um grupo repet\xedvel responde."],"ondeAparece":["Cadastro de um fato declarado do cat\xe1logo","Cadastro de um fato derivado por regra do cat\xe1logo","Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);